import{_ as e,o as r,c as a,a3 as o}from"./chunks/framework.BNNhFWPR.js";const p=JSON.parse('{"title":"Texture editor","description":"Draw images with layers and frames, import sprite sheets, and export images.","frontmatter":{"id":"texture-editor","title":"Texture editor","order":13,"description":"Draw images with layers and frames, import sprite sheets, and export images.","editUrl":"https://github.com/ATMO-Engine/atmo/edit/main/docs/en/manual/texture-editor.md"},"headers":[],"relativePath":"manual/texture-editor.md","filePath":"en/manual/texture-editor.md"}'),d={name:"manual/texture-editor.md"};function s(i,t,n,h,l,c){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="texture-editor" tabindex="-1">Texture editor <a class="header-anchor" href="#texture-editor" aria-label="Permalink to &quot;Texture editor&quot;">​</a></h1><p>The <a href="/latest/api/cpp/class/atmo-editor-textureeditor" class="atmo-ref atmo-ref--symbol">texture editor</a> draws images made of layers and animation frames. Open it with <strong>+</strong> in the tab bar.</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><code>.atx</code> images, the format of the editor, currently <a href="#known-issues">cannot be opened again</a>. Export your work to <code>.png</code>.</p></div><h2 id="draw" tabindex="-1">Draw <a class="header-anchor" href="#draw" aria-label="Permalink to &quot;Draw {#draw}&quot;">​</a></h2><p>A new image is 64 by 64 pixels. Change its size with <strong>Width</strong> and <strong>Height</strong>, up to 65535.</p><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td>Left mouse button</td><td>Draws or erases</td></tr><tr><td>Right mouse button</td><td>Moves the image, by dragging</td></tr><tr><td>Scroll</td><td>Zooms, from 0.5 to 10 times</td></tr></tbody></table><ul><li><strong>Draw</strong> paints with the color of the color picker, blended according to its opacity. <strong>Erase</strong> makes pixels transparent.</li><li><strong>Size</strong> is the diameter of the brush, in pixels.</li><li><strong>Preview</strong> shows the <a href="/latest/getting-started/projects#default-scene" class="atmo-ref atmo-ref--page" data-preview="Where projects are stored on your computer and how to reach their files with project:// paths.">default scene</a> of the project. It does nothing if none is set.</li></ul><p>There is no undo.</p><h2 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers {#layers}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>Effect</th></tr></thead><tbody><tr><td><code>+</code></td><td>Adds a layer</td></tr><tr><td><code>-</code></td><td>Deletes the layer</td></tr><tr><td><code>^</code> and <code>v</code></td><td>Move the selected layer up or down</td></tr><tr><td>Hide and Show</td><td>Change whether the layer is shown. The button above the list changes all of them.</td></tr></tbody></table><p>The first layer of the list is on top.</p><h2 id="frames" tabindex="-1">Frames <a class="header-anchor" href="#frames" aria-label="Permalink to &quot;Frames {#frames}&quot;">​</a></h2><p>Every layer has the same number of frames, up to 255. In the timeline, press a cell to select its layer and frame.</p><table tabindex="0"><thead><tr><th>Button</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Add Frame</strong></td><td>Adds a frame at the end</td></tr><tr><td><strong>Delete Frame</strong></td><td>Deletes the current frame, unless it is the only one</td></tr><tr><td><strong>Play</strong> and <strong>Pause</strong></td><td>Play the animation. Drawing is locked while it plays.</td></tr><tr><td><strong>Previous</strong> and <strong>Next</strong></td><td>Change the current frame</td></tr><tr><td><strong>FPS</strong></td><td>Speed of the animation, from 1 to 240</td></tr></tbody></table><h2 id="import" tabindex="-1">Import an image <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import an image {#import}&quot;">​</a></h2><p>Open a <code>.png</code>, <code>.jpg</code> or <code>.bmp</code> file from the file explorer of the editor, or with <strong>Open</strong> while a texture editor tab is active. The import window asks for:</p><ul><li><strong>Frame count</strong>, from 1 to 255;</li><li><strong>Frame width</strong> and <strong>Frame height</strong>, which are the size of the whole image by default.</li></ul><p>Frames are read from left to right, then from top to bottom. The result has a single layer. To import a plain image, keep the default values.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export {#export}&quot;">​</a></h2><p><strong>Export</strong> asks for a name and a format, and writes the file next to the open one.</p><table tabindex="0"><thead><tr><th>Format</th><th>Contents</th></tr></thead><tbody><tr><td><code>.png</code>, <code>.bmp</code>, <code>.jpg</code></td><td>The selected layers, blended. Frames are side by side in a single row: a sprite sheet.</td></tr><tr><td><code>.atx</code></td><td>The image with its layers and frames</td></tr></tbody></table><p>A sprite sheet can be imported again with the same frame size. <code>.jpg</code> has no transparency.</p><p><strong>Save</strong> writes the open file. If it is an image, it becomes a sprite sheet of all the layers, and its layers and frames are lost.</p><h2 id="use" tabindex="-1">Use the image in a game <a class="header-anchor" href="#use" aria-label="Permalink to &quot;Use the image in a game {#use}&quot;">​</a></h2><p>Export it to <code>.png</code> and write its path in <code>texture_path</code>: see <a href="/latest/manual/entities#sprite2d" class="atmo-ref atmo-ref--page" data-preview="What each entity type is for, and the component fields it has.">Sprite2d</a>. Sprites cannot use <code>.atx</code> files, and do not animate sprite sheets.</p><h2 id="file-explorer" tabindex="-1">File explorer <a class="header-anchor" href="#file-explorer" aria-label="Permalink to &quot;File explorer {#file-explorer}&quot;">​</a></h2><p>The file explorer lists the files of the project. Select a file or a folder, then:</p><table tabindex="0"><thead><tr><th>Button</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Add File</strong></td><td>Creates an empty file with the name in the field</td></tr><tr><td><strong>Add Folder</strong></td><td>Creates a folder</td></tr><tr><td><strong>Rename</strong></td><td>Renames the selected file or folder</td></tr><tr><td><strong>Delete</strong></td><td>Asks for confirmation, then deletes it</td></tr></tbody></table><h2 id="atx" tabindex="-1">The .atx format <a class="header-anchor" href="#atx" aria-label="Permalink to &quot;The .atx format {#atx}&quot;">​</a></h2><p>All numbers are little-endian.</p><table tabindex="0"><thead><tr><th>Data</th><th>Type</th></tr></thead><tbody><tr><td><code>ATMOIMG</code> and a zero byte</td><td>8 characters</td></tr><tr><td>Version, 1</td><td>32-bit unsigned integer</td></tr><tr><td>Number of layers</td><td>32-bit unsigned integer</td></tr><tr><td>Number of frames</td><td>32-bit unsigned integer</td></tr><tr><td>Width</td><td>32-bit unsigned integer</td></tr><tr><td>Height</td><td>32-bit unsigned integer</td></tr><tr><td>Then, for each layer:</td><td></td></tr><tr><td>Length of the name, and the name</td><td>32-bit unsigned integer, then characters</td></tr><tr><td>Visible</td><td>1 byte</td></tr><tr><td>Pixels of each frame, row by row</td><td>Four 32-bit decimals: red, green, blue, alpha</td></tr></tbody></table><h2 id="known-issues" tabindex="-1">Known issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;Known issues {#known-issues}&quot;">​</a></h2><ul><li>Opening an <code>.atx</code> file fails: the log says <code>file format not valid</code>, and the tab shows a blank image. Saving that tab replaces the file with the blank image.</li><li>The <strong>Dropdown</strong> button is a test and has no effect.</li></ul>',33)])])}const g=e(d,[["render",s]]);export{p as __pageData,g as default};
